<details class="advanced-filters"><summary class="button secondary">Bộ lọc thêm</summary><div class="filter-popover"><label>Từ ngày tổ chức<input type="date" name="from" value="{{ request('from') }}"></label><label>Đến ngày tổ chức<input type="date" name="to" value="{{ request('to') }}"></label><label>Ưu tiên<select name="priority"><option value="">Tất cả</option>@foreach(['low'=>'Thấp','normal'=>'Bình thường','high'=>'Cao','urgent'=>'Khẩn cấp'] as $key=>$label)<option value="{{ $key }}" @selected(request('priority')===$key)>{{ $label }}</option>@endforeach</select></label><label>Hạn thực hiện<select name="deadline"><option value="">Tất cả</option><option value="soon" @selected(request('deadline')==='soon')>Sắp đến hạn</option><option value="overdue" @selected(request('deadline')==='overdue')>Quá hạn</option></select></label></div></details>
